-- Simulation-only ledger. No payment integration, financial account or live flag.
CREATE TABLE referral_meta (org_id TEXT PRIMARY KEY REFERENCES organizations(id), version INTEGER NOT NULL DEFAULT 0, write_token TEXT, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1));
CREATE TABLE referral_grants (org_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('operator','reviewer','manager')), enabled INTEGER NOT NULL CHECK(enabled IN (0,1)), version INTEGER NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), PRIMARY KEY(org_id,user_id,role));
CREATE TABLE referral_rules (org_id TEXT NOT NULL REFERENCES organizations(id), version INTEGER NOT NULL, payload_json TEXT NOT NULL, effective_at TEXT NOT NULL, reason TEXT NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), PRIMARY KEY(org_id,version));
CREATE TABLE referral_members (org_id TEXT NOT NULL REFERENCES organizations(id), user_id TEXT NOT NULL REFERENCES users(id), level INTEGER NOT NULL CHECK(level BETWEEN 1 AND 3), version INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), major_violation INTEGER NOT NULL DEFAULT 0 CHECK(major_violation IN (0,1)), joined_at TEXT NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), PRIMARY KEY(org_id,user_id));
CREATE TABLE referral_level_history (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, user_id TEXT NOT NULL, level INTEGER NOT NULL CHECK(level BETWEEN 1 AND 3), effective_at TEXT NOT NULL, reason TEXT NOT NULL, proposal_id TEXT, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), FOREIGN KEY(org_id,user_id) REFERENCES referral_members(org_id,user_id));
CREATE TABLE referral_customers (org_id TEXT NOT NULL REFERENCES organizations(id), customer_ref TEXT NOT NULL CHECK(customer_ref LIKE 'SIM-%'), related_user_id TEXT REFERENCES users(id), created_at TEXT NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), PRIMARY KEY(org_id,customer_ref));
CREATE TABLE referral_cases (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, customer_ref TEXT NOT NULL, promoter_id TEXT NOT NULL, business_line TEXT NOT NULL CHECK(business_line IN ('junior','arts')), state TEXT NOT NULL CHECK(state IN ('pending','consented','rejected','corrected','expired','cancelled')), version INTEGER NOT NULL, created_at TEXT NOT NULL, confirmed_at TEXT, attribution_days INTEGER NOT NULL CHECK(attribution_days BETWEEN 1 AND 90), expires_at TEXT NOT NULL, evidence_json TEXT NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), FOREIGN KEY(org_id,customer_ref) REFERENCES referral_customers(org_id,customer_ref), FOREIGN KEY(org_id,promoter_id) REFERENCES referral_members(org_id,user_id));
CREATE UNIQUE INDEX referral_single_active_attribution ON referral_cases(org_id,customer_ref) WHERE state IN ('pending','consented');
CREATE TABLE referral_orders (id TEXT PRIMARY KEY, org_id TEXT NOT NULL, order_ref TEXT NOT NULL CHECK(order_ref LIKE 'SIM-%'), case_id TEXT NOT NULL REFERENCES referral_cases(id), customer_ref TEXT NOT NULL, promoter_id TEXT NOT NULL, business_line TEXT NOT NULL CHECK(business_line IN ('junior','arts')), product_id TEXT NOT NULL, version INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('observing','ready','processing','simulated_paid','invalid','disputed','cancelled')), paid_cents INTEGER NOT NULL CHECK(paid_cents>=0), excluded_cents INTEGER NOT NULL CHECK(excluded_cents>=0), refunded_eligible_cents INTEGER NOT NULL DEFAULT 0 CHECK(refunded_eligible_cents>=0), refunded_excluded_cents INTEGER NOT NULL DEFAULT 0 CHECK(refunded_excluded_cents>=0), reward_cents INTEGER NOT NULL CHECK(reward_cents>=0), settled_cents INTEGER NOT NULL DEFAULT 0 CHECK(settled_cents>=0), disputed INTEGER NOT NULL DEFAULT 0 CHECK(disputed IN (0,1)), snapshot_json TEXT NOT NULL, paid_at TEXT NOT NULL, observation_base_at TEXT NOT NULL, observed_at TEXT, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), UNIQUE(org_id,order_ref), FOREIGN KEY(org_id,promoter_id) REFERENCES referral_members(org_id,user_id), CHECK(excluded_cents<=paid_cents), CHECK(refunded_eligible_cents<=paid_cents-excluded_cents), CHECK(refunded_excluded_cents<=excluded_cents));
CREATE TABLE referral_proposals (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), request_id TEXT NOT NULL, request_digest TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('consent','order','qualify','payout','refund','correction','dispute','level','violation','rules')), target_id TEXT, target_version INTEGER, order_ref TEXT, proof_ref TEXT CHECK(proof_ref IS NULL OR proof_ref LIKE 'SIM-%'), payload_json TEXT NOT NULL, reason TEXT NOT NULL, maker_id TEXT NOT NULL REFERENCES users(id), reviewer_id TEXT REFERENCES users(id), state TEXT NOT NULL CHECK(state IN ('pending','approved','rejected')), version INTEGER NOT NULL, review_reason TEXT, created_at TEXT NOT NULL, reviewed_at TEXT, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), UNIQUE(org_id,request_id), CHECK(reviewer_id IS NULL OR reviewer_id<>maker_id));
CREATE TABLE referral_payouts (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), order_id TEXT NOT NULL UNIQUE REFERENCES referral_orders(id), proposal_id TEXT NOT NULL UNIQUE REFERENCES referral_proposals(id), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), budget_month TEXT NOT NULL, proof_ref TEXT NOT NULL CHECK(proof_ref LIKE 'SIM-%'), recorded_at TEXT NOT NULL, simulation_at TEXT NOT NULL, maker_id TEXT NOT NULL REFERENCES users(id), reviewer_id TEXT NOT NULL REFERENCES users(id), simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1), CHECK(maker_id<>reviewer_id));
CREATE TABLE referral_adjustments (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), order_id TEXT NOT NULL REFERENCES referral_orders(id), proposal_id TEXT NOT NULL REFERENCES referral_proposals(id), kind TEXT NOT NULL, before_cents INTEGER NOT NULL, after_cents INTEGER NOT NULL, difference_cents INTEGER NOT NULL, state TEXT NOT NULL CHECK(state='requires_manual_agreement'), reason TEXT NOT NULL, created_at TEXT NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1));
CREATE TABLE referral_appeals (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), order_id TEXT NOT NULL REFERENCES referral_orders(id), promoter_id TEXT NOT NULL REFERENCES users(id), reason TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('open','resolved')), created_at TEXT NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1));
CREATE TABLE referral_events (id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, payload_json TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, simulation INTEGER NOT NULL DEFAULT 1 CHECK(simulation=1));
CREATE INDEX referral_orders_promoter ON referral_orders(org_id,promoter_id,state);
CREATE INDEX referral_proposals_queue ON referral_proposals(org_id,state,created_at);

CREATE UNIQUE INDEX referral_one_live_order_proposal ON referral_proposals(org_id,order_ref) WHERE order_ref IS NOT NULL AND state IN ('pending','approved');

CREATE UNIQUE INDEX referral_one_live_evidence ON referral_proposals(org_id,kind,proof_ref) WHERE proof_ref IS NOT NULL AND state IN ('pending','approved');
